ALTER TABLE equipment_transactions ADD COLUMN IF NOT EXISTS deposit_paise BIGINT NOT NULL DEFAULT 0;
ALTER TABLE equipment_transactions ADD COLUMN IF NOT EXISTS deposit_status VARCHAR(30) NOT NULL DEFAULT 'NOT_REQUIRED';
CREATE TABLE equipment_inventory(id UUID PRIMARY KEY,facility_id UUID REFERENCES facilities(id),equipment_name VARCHAR(160) NOT NULL,total_quantity INT NOT NULL,available_quantity INT NOT NULL,deposit_paise BIGINT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE(facility_id,equipment_name));
CREATE TABLE support_ticket_history(id UUID PRIMARY KEY,ticket_id UUID NOT NULL REFERENCES support_tickets(id),action VARCHAR(40) NOT NULL,details VARCHAR(2000),actor_user_id UUID REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE membership_family_members(id UUID PRIMARY KEY,membership_id UUID NOT NULL REFERENCES customer_memberships(id),dependent_id UUID NOT NULL REFERENCES customer_dependents(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(membership_id,dependent_id));
CREATE TABLE training_installments(id UUID PRIMARY KEY,enrollment_id UUID NOT NULL REFERENCES training_enrollments(id),installment_no INT NOT NULL,amount_paise BIGINT NOT NULL,due_date DATE NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'DUE',paid_at TIMESTAMPTZ,UNIQUE(enrollment_id,installment_no));
CREATE TABLE tournament_standings(id UUID PRIMARY KEY,tournament_id UUID NOT NULL REFERENCES tournaments(id),team_id UUID NOT NULL,played INT NOT NULL DEFAULT 0,won INT NOT NULL DEFAULT 0,drawn INT NOT NULL DEFAULT 0,lost INT NOT NULL DEFAULT 0,points INT NOT NULL DEFAULT 0,score_for INT NOT NULL DEFAULT 0,score_against INT NOT NULL DEFAULT 0,tie_break_value NUMERIC(12,3) NOT NULL DEFAULT 0,UNIQUE(tournament_id,team_id));
CREATE TABLE scheduled_backup_audit(id UUID PRIMARY KEY,backup_type VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,location VARCHAR(500),started_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,details VARCHAR(1000));
